        assertProblem(post("/api/coupons", couponBody(Map.of("type", "RATE", "value", 101)), Map.of()), 400, "VALIDATION_ERROR");
        assertThat(post("/api/coupons", couponBody(Map.of("type", "RATE", "value", 100)), Map.of()).status()).isEqualTo(201);
