        JsonNode order = createOrder(uniqueUser(), code, item(p, 1)).body();

        assertThat(order.get("discount").asLong()).isEqualTo(1_499); // floor(1499.85)
        assertThat(order.get("totalPrice").asLong()).isEqualTo(8_500);
